import{_ as i,o,c as a,a5 as n}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — Sign In With Email","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-2-sign-in-with-email/plan.md","filePath":"feature/authentication/3-2-2-sign-in-with-email/plan.md"}'),t={name:"feature/authentication/3-2-2-sign-in-with-email/plan.md"};function c(r,e,l,h,s,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="plan-—-sign-in-with-email" tabindex="-1">Plan — Sign In With Email <a class="header-anchor" href="#plan-—-sign-in-with-email" aria-label="Permalink to &quot;Plan — Sign In With Email&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — Login email/password, phân nhánh 2FA khi bật.</p><h2 id="quyet-đinh-đa-chot-khac-spec-api-cu" tabindex="-1">Quyết định đã chốt (khác spec API cũ) <a class="header-anchor" href="#quyet-đinh-đa-chot-khac-spec-api-cu" aria-label="Permalink to &quot;Quyết định đã chốt (khác spec API cũ)&quot;">​</a></h2><p>Spec đề xuất login trả <code>{accessToken, refreshToken, require2FA}</code> <strong>cùng lúc</strong>. Nhưng AC yêu cầu &quot;2FA chặn trước khi cấp token&quot; → KHÔNG cấp access token nếu chưa qua 2FA.</p><p><strong>Chốt: twoFactorToken + /2fa/verify</strong> (xác nhận với Trung):</p><ul><li>Login email/pw đúng + 2FA <strong>bật</strong> → trả <code>LoginResponse(requireTwoFactor=true, twoFactorToken=...)</code> — <strong>KHÔNG</strong> có accessToken/refreshToken.</li><li>FE chuyển màn nhập mã → gọi <code>POST /2fa/verify { twoFactorToken, code }</code> (FR 3.2.7) để lấy token đầy đủ.</li><li>2FA tắt → trả token như bình thường.</li></ul><h2 id="ky-thuat" tabindex="-1">Kỹ thuật <a class="header-anchor" href="#ky-thuat" aria-label="Permalink to &quot;Kỹ thuật&quot;">​</a></h2><ul><li><code>AuthServiceImpl.login()</code>: <code>resolveByIdentifier(identifier)</code> → <code>checkStatus(user)</code> (DEACTIVATED → 403 <code>ACCOUNT_DEACTIVATED</code>, không active/status khác → 403 <code>ACCOUNT_SUSPENDED</code>) → verify password → 2FA bật? → trả <code>LoginResponse.twoFactorChallenge(twoFactorToken)</code> : <code>completeLogin(user, role)</code>.</li><li><code>JwtUtil.generateTwoFactorToken(userId)</code> — JWT ngắn hạn 5 phút, claim <code>type=2fa</code>.</li><li><code>completeLogin()</code> — phát access + refresh, blacklist cũ, audit log.</li></ul><h2 id="luong" tabindex="-1">Luồng <a class="header-anchor" href="#luong" aria-label="Permalink to &quot;Luồng&quot;">​</a></h2><ol><li>Validate <code>identifier</code> (email/phone) + chuẩn hóa → check tồn tại → không thấy → 401 <code>INVALID_CREDENTIALS</code>.</li><li><code>checkStatus</code> → DEACTIVATED → 403 <code>ACCOUNT_DEACTIVATED</code>; không active/status khác → 403 <code>ACCOUNT_SUSPENDED</code>.</li><li>Verify password (bcrypt), hoặc <code>passwordHash=null</code> (OAuth-only) → sai → 401 <code>INVALID_CREDENTIALS</code> (không tiết lộ).</li><li><code>twoFactorEnabled</code> → challenge : completeLogin.</li></ol><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>User enum: mọi nhánh sai thông tin trả 401 chung.</li></ul><h2 id="dev-quick-login-repair-—-2026-10-04" tabindex="-1">Dev Quick Login repair — 2026-10-04 <a class="header-anchor" href="#dev-quick-login-repair-—-2026-10-04" aria-label="Permalink to &quot;Dev Quick Login repair — 2026-10-04&quot;">​</a></h2><ol><li><code>src/main/resources/seed/dev-quick-login.sql</code>: PostgreSQL transaction/guard tạo fixture cho ba email legacy khi thiếu; agency/workspace/package/profile có UUID riêng cố định để rerun idempotent. Password bcrypt qua pgcrypto, chỉ áp dụng tài khoản mới. Reuse existing seed tool conventions, không thêm API công khai hay migration production.</li><li><code>brandhub-web/src/components/auth/DevQuickLogin.tsx</code>: giữ Admin/Owner/Client landing; Manager/Creator gọi workspaceService.list sau setAuth, chọn myRole thay landingPath UUID. Có fallback và error giữ phiên thật; challenge 2FA đi /2fa-verify.</li><li><code>src/i18n/locales/{vi,en}/auth.json</code>: <code>login.devWorkspaceMissing</code>.</li><li>Playwright fixture chứng minh Manager/Creator được đưa vào UUID API trả, không chọn Workspace sai role; Client/Owner/Admin landing giữ nguyên, 2FA không đọc profile. Live browser cả bốn role, verify DB rerun không thêm record hoặc sửa dữ liệu ngoài fixture; không chạy bulk reseed.</li></ol>',14)])])}const p=i(t,[["render",c]]);export{g as __pageData,p as default};
